#[cfg(test)]
mod webhook_enum_tests {
    use super::{WebhookMethod, WebhookMode};

    #[test]
    fn mode_wire_strings_are_lowercase() {
        assert_eq!(
            serde_json::to_string(&WebhookMode::Event).unwrap(),
            "\"event\""
        );
        assert_eq!(
            serde_json::to_string(&WebhookMode::Ping).unwrap(),
            "\"ping\""
        );
    }

    #[test]
    fn method_wire_strings_are_uppercase() {
        assert_eq!(
            serde_json::to_string(&WebhookMethod::Get).unwrap(),
            "\"GET\""
        );
        assert_eq!(
            serde_json::to_string(&WebhookMethod::Post).unwrap(),
            "\"POST\""
        );
    }

    #[test]
    fn db_string_values_match_wire() {
        use sea_orm::ActiveEnum;
        assert_eq!(WebhookMode::Event.to_value(), "event");
        assert_eq!(WebhookMethod::Post.to_value(), "POST");
    }
}

#[cfg(test)]
mod mode_bridge_tests {
    use super::Mode as DbMode;
    use koji_core::Mode as CoreMode;

    #[test]
    fn bridges_both_directions() {
        assert_eq!(CoreMode::from(DbMode::Fort), CoreMode::Fort);
        assert_eq!(DbMode::from(CoreMode::Quest), DbMode::Quest);
    }

    #[test]
    fn db_string_values_are_lowercase() {
        use sea_orm::ActiveEnum;
        assert_eq!(DbMode::Pokemon.to_value(), "pokemon");
    }
}
